\begin{theorem}[full-spectrum Gram positivity]\label{thm:setting-gram}
Let $\Lambda_1,\dots,\Lambda_N$ be finite-order constant-coefficient derivative-evaluation functionals on $\T^3_{24}$, $\Lambda_i(f)=(P_i(\partial)f)(x_i)$ with polynomial symbols $P_i$, and let $\mathcal T_i=P_i(-\partial)\delta_{x_i}$ be the associated distributions, $\langle\mathcal T_i,\varphi\rangle=\Lambda_i(\varphi)$. The covariance matrix $\bigl(\Cov(\Lambda_if,\Lambda_jf)\bigr)_{i,j\le N}$ is positive definite if and only if $\mathcal T_1,\dots,\mathcal T_N$ are linearly independent.

In particular, if at each of the distinct support points the polynomial symbols of the differential operators evaluated there are linearly independent, then the covariance matrix is positive definite.
\end{theorem}

\begin{theorem}[generic-fold dimension cancellation]\label{thm:contact-cancellation}
Let $d\ge1$. Assume Hypothesis~\ref{hyp:contact-regular} for every compact $\mathcal K\subset\R\times(0,\infty)$, and that the two-point Kac--Rice formula holds for the ordered typed pair process. Then:
\begin{enumerate}[(i)]
\item The Kac--Rice density of the all-typed pair measure of maxima and index-$(d-1)$ critical points with respect to $dx\,r^{d-1}dr\,d\sigma_{d-1}(t)\,db\,d\kappa$ is
\begin{equation}\label{eq:contact-KR}
\frac{r^3}6\,K^{\rm all}_r=\frac{r^3}6\,p_\Pi\,Z_r ,
\end{equation}
where $r^3/6$ is the exact Jacobian from the saddle value to $\kappa$.

\begin{theorem}[dimension-independent generic-fold exponent]\label{thm:contact-exponent}
In the setting of Proposition~\ref{prop:contact-pushforward}, whenever the limiting selected mass $c$ in \eqref{eq:contact-c} is finite and strictly positive,
\begin{equation}\label{eq:contact-asymp}
\nu_{s,\varrho}(\ell)=c\,\ell^{-1/3}\bigl(1+o(1)\bigr),\qquad\ell\downarrow0,
\end{equation}
so the short-lifetime density exponent is $-1/3$ in every ambient dimension. Selection affects the coefficient through $s_0$; it does not affect the exponent unless the limiting selected mass vanishes or introduces an additional singular scale.
\end{theorem}

\begin{theorem}[exact finite-side coefficient reduction]\label{thm:coefficient-main}
Let $L\in(0,\infty]$, and let $G^{\rm all}_0$ be given by \eqref{eq:coefficient-G0} for the covariance $K_L$. Then
\begin{equation}\label{eq:coefficient-coefint}
\frac{6^{2/3}}{18}\int_{S^2}\int_{\R}\int_0^\infty\kappa^{-2/3}\,G^{\rm all}_0(t,b,\kappa)\,d\kappa\,db\,d\sigma_2(t)
\end{equation}
is exactly $c_{3,L}$ of \eqref{eq:coefficient-cL}--\eqref{eq:coefficient-B3}. When the contact limit and the compact elder selection hold for the side-$L$ field, \eqref{eq:coefficient-coefint} is its complete selected $H_0$ short-lifetime coefficient, as in Theorem~3.9 of the main text; for $L=24$ this is Proposition~\ref{prop:limit-hypotheses} and Corollary~\ref{cor:limit-coefficient}. In particular the coefficient $c_{3,24}$ of Theorem~2.1 of the main text is given by (2.9) there. Every input of \eqref{eq:coefficient-cL} is an explicit finite-dimensional covariance object derived from $K_L$ at the origin, and the formula is independent of the chosen transverse frame (Lemma~\ref{lem:coefficient-frame}).
\end{theorem}

\begin{theorem}[the cone constant]\label{thm:coefficient-D2}
Let $G_2$ be a standard $\mathrm{GOE}_2$ matrix, $Z\sim N(0,1)$ independent of $G_2$, and $Q=G_2+\sqrt{2/3}\,Z\,I_2$. Then
\begin{equation}\label{eq:coefficient-D2}
D_2=\E\bigl[(\det Q)^2\,\ind_{\{Q\prec0\}}\bigr]=\frac{29}{6}-\sqrt6 .
\end{equation}
\end{theorem}

\begin{corollary}[the coefficient on $\R^3$]\label{cor:coefficient-cinf}
\begin{equation}\label{eq:coefficient-cinf}
c_{3,\infty}=\frac{2^{1/6}\,3^{1/3}\,(29\sqrt6-36)\,\Gamma(1/6)}{432\,\pi^{5/2}}
=2^{-23/6}\,3^{-8/3}\,(29\sqrt6-36)\,\Gamma(1/6)\,\pi^{-5/2},
\end{equation}
and
\begin{equation}\label{eq:coefficient-cinf-decimal}
c_{3,\infty}=0.041775931840598343342936665428575556466681519661\ldots .
\end{equation}
\end{corollary}

\begin{theorem}[the side-24 correction]\label{thm:correction-main}
Let $d\in\{2,3\}$ and $q=e^{-288}$. Then
\begin{equation}\label{eq:correction-main}
\Bigl|\frac{c_{d,24}}{c_{d,\mathrm{ref}}}-1-P_d(24)\,q\Bigr|<10^{-216},
\end{equation}
where
\begin{equation}\label{eq:correction-Pd}
\begin{gathered}
P_d(L)=-\frac{10L^6}{3(d+2)(d+4)}+\frac{(d+4)L^4}{d+2}-dL^2,\\
P_2(24)=-26045568,\qquad P_3(24)=-\frac{620813376}{35}.
\end{gathered}
\end{equation}
In particular $c_{d,24}<c_{d,\mathrm{ref}}$ for $d=2$ and for $d=3$.
\end{theorem}

\begin{corollary}[(2.10) of the main text]\label{cor:correction-main}
With $P_3(L)=-L^2(10L^4-147L^2+315)/105$,
\begin{equation}\label{eq:correction-main3}
\frac{c_{3,24}}{c_{3,\infty}}-1=P_3(24)\,e^{-288}+\varepsilon_{24}=-\frac{620813376}{35}\,e^{-288}+\varepsilon_{24},\qquad|\varepsilon_{24}|<10^{-216},
\end{equation}
and $c_{3,24}<c_{3,\infty}$.
\end{corollary}

\begin{theorem}[elder selection on compact marks]\label{thm:selection-main}
For every compact $I_b\subset\R$ and every compact $I_\kappa\subset(0,\infty)$ there are $r_0>0$ and $C_{\rm sel}<\infty$ such that, under the all-typed maximum--index-two-saddle Palm law \eqref{eq:selection-palm},
\begin{equation}\label{eq:selection-main}
\sup_{t\in S^2,\ b\in I_b,\ \kappa\in I_\kappa}\bigl[1-p_r(t,b,\kappa)\bigr]\le C_{\rm sel}\,r^3,\qquad0<r\le r_0 .
\end{equation}
In particular, the elder-rule selection probability tends to one uniformly on compact positive mark sets.
\end{theorem}

\begin{proposition}[the hypotheses for the side-24 field]\label{prop:limit-hypotheses}
Let $\varrho\in(0,12)$. For the side-24 field, (H1)--(H3) of Theorem~\ref{thm:limit-interchange} hold, with $G^{\mathrm{sel}}_0=G^{\mathrm{all}}_0$. More precisely, there are constants $C,c>0$ and an integer $N$, depending on $\varrho$, such that for all $0<r<\varrho$ and all $(t,b,\kappa)\in S^2\times\R\times(0,\infty)$
\begin{equation}\label{eq:limit-majorant}
0\le\kappa^{-2/3}G^{\mathrm{sel}}_r(t,b,\kappa)\le\kappa^{-2/3}G^{\mathrm{all}}_r(t,b,\kappa)\le C\bigl[1+(|b|+\kappa)^N\bigr]e^{-c(b^2+\kappa^2)}\,\kappa^{-2/3},
\end{equation}
and the right side is integrable on $S^2\times\R\times(0,\infty)$, including $\kappa\downarrow0$. Moreover $0<c_{3,24}<\infty$.
\end{proposition}

\begin{corollary}[the selected coefficient]\label{cor:limit-coefficient}
For $0<r<12$ let $\psi_r=\frac{6^{2/3}}{18}\,\kappa^{-2/3}G^{\mathrm{all}}_r$ be the nonnegative all-typed rescaled contact integrand on $S^2\times\R\times(0,\infty)$; the selected integrand is $p_r\,\psi_r=\frac{6^{2/3}}{18}\,\kappa^{-2/3}G^{\mathrm{sel}}_r$. Then, with integrals over $S^2\times\R\times(0,\infty)$ with respect to $d\kappa\,db\,d\sigma_2(t)$,
\begin{equation}\label{eq:limit-ident}
\lim_{r\downarrow0}\int p_r\,\psi_r=\lim_{r\downarrow0}\int\psi_r=c_{3,24},
\end{equation}
and the constant \eqref{eq:limit-const} is the coefficient (2.9) of the main text. Therefore the exact finite-side coefficient (2.9) is the selected short-lifetime coefficient of the finite nonessential superlevel $H_0$ bars:
\begin{equation}\label{eq:limit-law}
\nu_{3,24}(\ell)=c_{3,24}\,\ell^{-1/3}\bigl(1+o(1)\bigr),\qquad\ell\downarrow0 .
\end{equation}
\end{corollary}

\begin{theorem}[bounded remainder]\label{thm:rate-bounded}
Let $d\ge2$ and $L>0$, and let
\[
\nu_{\cand}=\nu^{\rm near}_{\cand}+\nu^{\rm far}_{\cand},\qquad \nu_{\eld}=\nu^{\rm near}_{\eld}+\nu^{\rm far}_{\eld}
\]
be the versions, given by Hypotheses~\ref{hyp:rate-KR} and~\ref{hyp:rate-far}, of the densities per unit volume of all candidate pairs and of all finite ordinary superlevel $H_0$ bars on $\T^d_L$, with all birth heights, all gap marks $k>0$, all orientations and all separations, and with the essential class of the global maximum excluded. There are $\ell_*>0$ and $C<\infty$ such that, for $0<\ell\le\ell_*$,
\begin{equation}\label{eq:rate-R1}
\begin{aligned}
&\bigl|\nu_{\cand}(\ell)-c_{d,L}\,\ell^{-1/3}\bigr|\le C,\\
&0\le\nu_{\cand}(\ell)-\nu_{\eld}(\ell)\le C,\\
&\bigl|\nu_{\eld}(\ell)-c_{d,L}\,\ell^{-1/3}\bigr|\le C .
\end{aligned}
\end{equation}
\end{theorem}

\begin{theorem}[Theorem R$^+$: the constant term of the remainder]\label{thm:remainder-vanish}
For every fixed $d\ge2$ and $L>0$, and for the canonical marked Kac--Rice density versions (the versions for which Proposition~\ref{prop:remainder-Z}(i) is stated; $\nu_{\cand}$ and $\nu_{\eld}$ are the unrestricted densities), as $\ell\downarrow0$,
\begin{align}
\nu_{\cand}(\ell)&=c_{d,L}\,\ell^{-1/3}+B_{d,L}+o(1),\label{eq:remainder-Rp1}\\
\nu_{\eld}(\ell)&=c_{d,L}\,\ell^{-1/3}+o(1)=c_{d,L}\,\ell^{-1/3}\bigl(1+o(\ell^{1/3})\bigr).\label{eq:remainder-Rp2}
\end{align}
Moreover, for every $r_0\in(0,r_0^*]$, as $\ell\downarrow0$,
\begin{equation}\label{eq:remainder-Rp3}
\begin{gathered}
\nu_{\cand}^{\mathrm{near},r_0}(\ell)-c_{d,L}\,\ell^{-1/3}\to\int_{0<\dist(0,y)<r_0}\int_\R\Psi_0(b,y)\,db\,dy,\\
\bigl|\nu_{\cand}^{\mathrm{near},r_0}(\ell)-c_{d,L}\,\ell^{-1/3}\bigr|\le C\bigl(r_0+\ell^2r_0^{-7}\bigr),
\end{gathered}
\end{equation}
the bound holding for every $\ell>0$.
\end{theorem}

\begin{theorem}[Theorem R$^{++}$: rate of the elder remainder]\label{thm:remainder-rate}
For every fixed $d\ge2$ and $L>0$, and for the canonical marked Kac--Rice density version of the elder density, there are $C<\infty$ and $\ell_0\in(0,1]$ depending on $d,L$ only such that
\begin{equation}\label{eq:remainder-Rpp}
\bigl|\nu_{\eld}(\ell)-c_{d,L}\,\ell^{-1/3}\bigr|\le C\ell^{1/4},\qquad 0<\ell\le\ell_0;
\end{equation}
equivalently, $\nu_{\eld}(\ell)=c_{d,L}\,\ell^{-1/3}\bigl(1+O(\ell^{7/12})\bigr)$ as $\ell\downarrow0$.
\end{theorem}

\begin{lemma}[the cap-region bound]\label{lem:remainder-capK}
Let $r_0$ be as in \eqref{eq:rate-r0}. There are $C$ and $N$ such that, for $0<r\le r_0$, $b\in\R$, $k\ge r$ and every frame,
\begin{equation}\label{eq:remainder-capK}
\E_Q\Bigl[\frac{W_r}{r^2}\,\ind_{G_r^c}\Bigr]\le C\,\frac{r^3}k\,P^N .
\end{equation}
\end{lemma}

\begin{theorem}[Theorem CU: the cusp term of the elder law]\label{thm:cusp-CU}
For every $d\ge2$ and $L>0$, and for the canonical marked Kac--Rice density version of the elder density, as $\ell\downarrow0$,
\begin{equation}\label{eq:cusp-CU1}
\nu_{\eld}(\ell)=c_{d,L}\,\ell^{-1/3}+c_1\,\ell^{1/4}+o(\ell^{1/4}),
\end{equation}
\begin{equation}\label{eq:cusp-c1}
c_1=-\frac{192}7\,2^{1/4}\int_{S^{d-1}}\int_\R\pi_0\bigl(u;v_0(b,0)\bigr)\,\E_0\Bigl[|Y|^{7/4}|\Delta|^{1/4}\ind\{A\prec0\}\Bigm|b\Bigr]\,db\,d\sigma(u),
\end{equation}
and $c_1\in(-\infty,0)$. Equivalently, with $G:=\nabla f(0)$, $V_u:=(\partial_u^2f,\nabla_\Theta\partial_uf)(0)$, $t_u:=\partial_u^3f(0)$ and $\tau_u^2:=\Var(t_u\mid G=0)$ (odd and even jets are independent \cite[\S15]{parentP}; Lemma~\ref{lem:parent-parity}),
\begin{multline}\label{eq:cusp-c1parity}
c_1=-\frac{192}7\,2^{1/4}\int_{S^{d-1}}p_G(0)\,p_{V_u}(0)\,(2\pi)^{-1/2}\tau_u^{-1}\\
\times\E\Bigl[|Y|^{7/4}|\Delta|^{1/4}\ind\{A\prec0\}\Bigm|V_u=0,\ G=0,\ t_u=0\Bigr]\,d\sigma(u).
\end{multline}
So $\nu_{\eld}(\ell)=c_{d,L}\ell^{-1/3}\bigl(1+(c_1/c_{d,L})\ell^{7/12}+o(\ell^{7/12})\bigr)$.
\end{theorem}

\begin{theorem}[the elder density to third order]\label{thm:third-E3}
For every $d\ge2$ and $L>0$, and for the canonical marked Kac--Rice density version of $\nu_\eld$, as $\ell\downarrow0$,
\begin{equation}\label{eq:third-E30}
\nu_\eld(\ell)=c_{d,L}\ell^{-1/3}+c_1\ell^{1/4}+c_2\ell^{1/3}+\nu_\eld^{{\rm far},r_0^*}(\ell)+O(\ell^{4/11}),\qquad 0\le\nu_\eld^{{\rm far},r_0^*}(\ell)\le C\ell^{1/3}.
\end{equation}
Consequently
\begin{align}
\nu_\eld(\ell)&=c_{d,L}\ell^{-1/3}+c_1\ell^{1/4}+O(\ell^{1/3}),\label{eq:third-E31}\\
\nu_\eld(\ell)&\ge c_{d,L}\ell^{-1/3}+c_1\ell^{1/4}+c_2\ell^{1/3}-C\ell^{4/11},\label{eq:third-E32}
\end{align}
and, by \eqref{eq:third-farrate} at $\rho=r_0^*$,
\begin{equation}\label{eq:third-E33}
\nu_\eld(\ell)=c_{d,L}\ell^{-1/3}+c_1\ell^{1/4}+c_2\ell^{1/3}+O(\ell^{4/11}).
\end{equation}
More precisely, for $0<\theta\le4/11$, $\nu_\eld(\ell)-c_{d,L}\ell^{-1/3}-c_1\ell^{1/4}-c_2\ell^{1/3}=O(\ell^\theta)$ if and only if $\nu_\eld^{{\rm far},r_0^*}(\ell)=O(\ell^\theta)$ (both hold for $\theta\le1/3$), and the three-term law with remainder $o(\ell^{1/3})$ holds if and only if $\nu_\eld^{{\rm far},r_0^*}(\ell)=o(\ell^{1/3})$. Only \eqref{eq:third-E33} uses \eqref{eq:third-farrate}.
\end{theorem}

\begin{theorem}[the elder density, remainder $\ell^{3/7}$]\label{thm:third-E3plus}
For every $d\ge2$ and $L>0$, and for the canonical marked Kac--Rice density version of $\nu_\eld$, as $\ell\downarrow0$,
\begin{equation}\label{eq:third-E3p0}
\nu_\eld(\ell)=c_{d,L}\ell^{-1/3}+c_1\ell^{1/4}+c_2\ell^{1/3}+\nu_\eld^{{\rm far},r_0^*}(\ell)+O(\ell^{3/7}),
\end{equation}
and, by \eqref{eq:third-farrate} at $\rho=r_0^*$,
\begin{equation}\label{eq:third-E3p1}
\nu_\eld(\ell)=c_{d,L}\ell^{-1/3}+c_1\ell^{1/4}+c_2\ell^{1/3}+O(\ell^{3/7}).
\end{equation}
The elder density from the intermediate separations (the part of the integral in \eqref{eq:third-ident} with $\ell^{2/9}\le r\le r_0^*$, at $r_0=r_0^*$) is $O(\ell^{4/9}\log(1/\ell))$. For $0<\theta\le3/7$, $\nu_\eld(\ell)-c_{d,L}\ell^{-1/3}-c_1\ell^{1/4}-c_2\ell^{1/3}=O(\ell^\theta)$ if and only if $\nu^{{\rm far},r_0^*}_\eld(\ell)=O(\ell^\theta)$. Only \eqref{eq:third-E3p1} uses \eqref{eq:third-farrate}.
\end{theorem}

